<?php
require __DIR__.'/includes/bootstrap.php';require_login();$uid=current_user()['id'];$cid=(int)($_GET['id']??0);$st=db()->prepare("SELECT c.*,p.title,p.price,p.id product_id,b.name buyer_name,s.name seller_name FROM conversations c JOIN products p ON p.id=c.product_id JOIN users b ON b.id=c.buyer_id JOIN users s ON s.id=c.seller_id WHERE c.id=? AND (c.buyer_id=? OR c.seller_id=?)");$st->execute([$cid,$uid,$uid]);$c=$st->fetch();if(!$c){http_response_code(404);exit('Conversation not found');}$other=$uid==$c['buyer_id']?$c['seller_name']:$c['buyer_name'];$page_title='Chat';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$body=trim($_POST['body']??'');$offer=trim($_POST['offer']??'');if($body===''&&$offer==='')$error='Write a message or enter an offer.';elseif($offer!==''&&(!is_numeric($offer)||(float)$offer<=0))$error='Enter a valid offer amount.';else{$text=$body;if($offer!=='')$text.=($text?"\n":'').'PRICE OFFER: ₦'.number_format((float)$offer);$st=db()->prepare('INSERT INTO messages(conversation_id,sender_id,body) VALUES(?,?,?)');$st->execute([$cid,$uid,$text]);db()->prepare('UPDATE conversations SET updated_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$cid]);header('Location: '.url('chat.php?id='.$cid));exit;}}
$st=db()->prepare('SELECT m.*,u.name FROM messages m JOIN users u ON u.id=m.sender_id WHERE conversation_id=? ORDER BY m.created_at');$st->execute([$cid]);$msgs=$st->fetchAll();include __DIR__.'/includes/header.php';?>
<div class="chat-head"><div><span class="eyebrow">NEGOTIATION</span><h1><?= e($c['title']) ?></h1><p>Chatting with <?= e($other) ?> · Listed at <?= money($c['price']) ?></p></div><a class="btn btn-light" href="<?= e(url('product.php?id='.$c['product_id'])) ?>">View item</a></div><?php if($error): ?><div class="error"><?= e($error) ?></div><?php endif; ?><div class="chat-box"><?php foreach($msgs as $m): ?><div class="message <?= $m['sender_id']==$uid?'mine':'theirs' ?>"><small><?= e($m['name']) ?> · <?= e($m['created_at']) ?></small><p><?= nl2br(e($m['body'])) ?></p></div><?php endforeach; ?><?php if(!$msgs): ?><p class="muted">Start the conversation. Ask a question or make an offer.</p><?php endif; ?></div><form method="post" class="form-card chat-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Message<textarea name="body" rows="3" placeholder="Is this item still available?"></textarea></label><label>Your price offer (NGN, optional)<input type="number" min="1" step="1" name="offer" placeholder="Enter your offer"></label><button class="btn">Send message / offer</button></form>
<?php include __DIR__.'/includes/footer.php'; ?>
